package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class FimlChecks {
    static int checks;
    static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid FIML input accepted");}catch(IllegalArgumentException expected){checks++;}}
    static SemModel.Model saturated(){List<SemModel.Parameter> params=new ArrayList<>();params.add(new SemModel.Parameter("Variance X",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,0,0)),1,1,.000001,null));params.add(new SemModel.Parameter("Variance Y",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,1,1)),1,1,.000001,null));params.add(new SemModel.Parameter("Covariance XY",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,0,1)),.2,1));params.add(new SemModel.Parameter("Mean X",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),0,1));params.add(new SemModel.Parameter("Mean Y",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,1,0)),0,1));return new SemModel.Model(List.of("X","Y"),new int[]{0,1},new double[2][2],new double[2][2],new double[2],params);}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]);Files.createDirectories(out);Random rng=new Random(551199);double[][] complete=new double[420][2];for(var row:complete){double x=rng.nextGaussian();row[0]=2+x;row[1]=-1+.6*x+.8*rng.nextGaussian();}var model=saturated();var options=FimlSem.Options.defaults();var baseline=FimlSem.fit(complete,model,options);var ordinary=CovarianceSem.fit(complete,model,new CovarianceSem.Options(1500,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,true,.95,CovarianceSem.Information.OBSERVED));require(baseline.converged()&&baseline.locallyIdentified(),"Complete FIML regularity");require(Math.abs(baseline.logLikelihood()-ordinary.logLikelihood())<1e-6,"Complete likelihood reduction");for(int j=0;j<5;j++)require(Math.abs(baseline.estimates()[j]-ordinary.estimates()[j])<1e-5,"Complete raw parameter reduction");
        double[][] missing=Matrices.copy(complete);for(int i=0;i<missing.length;i++){if(i%5==0)missing[i][0]=Double.NaN;if(i%7==0)missing[i][1]=Double.NaN;}double[][] before=Matrices.copy(missing);var fit=FimlSem.fit(missing,model,options);require(fit.converged()&&fit.locallyIdentified(),"Incomplete likelihood regularity");require(fit.emptyRows()==12&&fit.observations()==408&&fit.observedPatterns()==3,"Actual observed-pattern accounting");require(Arrays.deepEquals(before,missing),"Missing source remains unchanged");
        var likelihood=new SemObservedLikelihood(missing,model);double[] theta=likelihood.initial();var analytic=likelihood.evaluate(theta);for(int j=0;j<theta.length;j++){double[] a=theta.clone(),b=theta.clone();a[j]+=1e-5;b[j]-=1e-5;double derivative=(likelihood.evaluate(a).value()-likelihood.evaluate(b).value())/2e-5;require(Math.abs(derivative-analytic.gradient()[j])<2e-7,"Observed-pattern analytic gradient");}double[][] scores=likelihood.caseScores(theta);for(int j=0;j<theta.length;j++){double mean=0;for(var row:scores)mean+=row[j]/likelihood.observations;require(Math.abs(mean-analytic.gradient()[j])<1e-9,"Case scores aggregate to pattern gradient");}
        double[][] absent=Matrices.copy(missing);for(var row:absent)row[1]=Double.NaN;reject(()->FimlSem.fit(absent,model,options));double[][] infinite=Matrices.copy(missing);infinite[0][0]=Double.POSITIVE_INFINITY;reject(()->FimlSem.fit(infinite,model,options));Thread.currentThread().interrupt();try{FimlSem.fit(missing,model,options);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        double[][] factors=new double[360][6];for(var row:factors){double x=rng.nextGaussian(),y=.5*x+.8*rng.nextGaussian();for(int j=0;j<6;j++)row[j]=1+j*.3+(1+.1*(j%3))*(j<3?x:y)+.6*rng.nextGaussian();}var blocks=List.of(new PlsSem.Block("Factor X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("Factor Y",new int[]{3,4,5},PlsSem.Mode.A));var names=List.of("X1","X2","X3","Y1","Y2","Y3");var factorModel=SemModel.reflective(names,factors,blocks,List.of(new PlsSem.Edge(0,1)),true,true).model();for(var row:factors)for(int j=0;j<6;j++)if(rng.nextDouble()<.22)row[j]=Double.NaN;var factorFit=FimlSem.fit(factors,factorModel,options);require(factorFit.converged()&&factorFit.locallyIdentified(),"Latent measurement/structural FIML fit");require(factorFit.observedPatterns()>10,"Many missingness patterns are fitted");
        Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject receipt=new JsonObject();receipt.add("completeData",gson.toJsonTree(complete));receipt.add("missingData",gson.toJsonTree(missing));receipt.add("complete",gson.toJsonTree(baseline));receipt.add("ordinary",gson.toJsonTree(ordinary));receipt.add("fit",gson.toJsonTree(fit));receipt.add("factorData",gson.toJsonTree(factors));receipt.add("factorFit",gson.toJsonTree(factorFit));receipt.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),gson.toJson(receipt));System.out.println("FIML checks: "+checks);
    }
}
